#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/release.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="The release library: the steps of each release:<project>:<kind> task"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# The steps of a [release.<project>.<kind>] table of repo.toml. Each
# release:<project>:<kind> task calls main(project, kind). See
# docs/design/repo.md of bootstrap ("The release tasks").
#
# A task kind runs its preflight tasks, then its task with its args. It
# reads no level, and makes no commit and no tag. A tag kind:
#
#   1. With a release commit `ops: release <tag>` on its branch and no tag,
#      it tags the first commit of the branch that has that commit (resume).
#   2. With from, it tags HEAD of its branch with the last version of the
#      from kind (promotion).
#   3. Else it reads the level of releases.<project>; NONE is nothing to do.
#      It runs the preflight tasks, bumps the version, commits the version
#      file and the cleared level, lands the commit as the landing of the
#      branch says, and tags the landed commit.

import json
import os
import re
import shlex
import subprocess
import sys
import time
import tomllib

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

LEVELS = ["NONE", "PATCH", "MINOR", "MAJOR"]
SEMVER = r"(\d+)\.(\d+)\.(\d+)"


def git(*args):
  """Run git. Returns (code, stdout without the last line break)."""
  result = subprocess.run(["git", *args], check=False, stdout=subprocess.PIPE, text=True)
  return result.returncode, result.stdout.rstrip("\n")


def must(*args):
  """Run a command. A failure stops the task with its code."""
  rc = subprocess.run(list(args), check=False).returncode
  if rc != 0:
    sys.exit(rc)


def value(key):
  """The value of a key of .config/bootstrap/."""
  return helpers.bootstrap_get(key)["value"]


def bootstrap(*args):
  """Run the engine: BOOTSTRAP_BIN, else the bootstrap of mise."""
  binary = [os.environ["BOOTSTRAP_BIN"]] if os.environ.get("BOOTSTRAP_BIN") else ["mise", "x", "--", "bootstrap"]
  must(*binary, *args)


def tag_regex(template):
  """The regex of the tags of <template>: {version} is a semantic version."""
  parts = template.split("{version}")
  return re.compile("^" + SEMVER.join(re.escape(p) for p in parts) + "$")


def last_version(template):
  """The highest version of the tags of <template>, as a tuple, or None."""
  regex = tag_regex(template)
  best = None
  for name in git("tag", "--list")[1].splitlines():
    m = regex.match(name)
    if m:
      v = tuple(int(x) for x in m.groups()[:3])
      best = v if best is None or v > best else best
  return best


def show(v):
  return ".".join(str(x) for x in v)


def bump(v, level):
  major, minor, patch = v
  if level == "MAJOR":
    return (major + 1, 0, 0)
  if level == "MINOR":
    return (major, minor + 1, 0)
  return (major, minor, patch + 1)


def tag_exists(name):
  return git("rev-parse", "--quiet", "--verify", f"refs/tags/{name}")[0] == 0


def read_version(path):
  """The version of a .json file or of a Cargo.toml, as a tuple."""
  if path.endswith(".json"):
    with open(path) as f:
      text = json.load(f).get("version", "")
  else:
    with open(path, "rb") as f:
      text = tomllib.load(f).get("package", {}).get("version", "")
  m = re.fullmatch(SEMVER, str(text))
  if not m:
    helpers.print_error(f"{path} has no version X.Y.Z.")
    sys.exit(1)
  return tuple(int(x) for x in m.groups())


def write_version(path, old, new):
  """Write <new> into the version file <path>. A Cargo.toml also updates its
  package in the Cargo.lock of its folder or of the root."""
  with open(path) as f:
    text = f.read()
  if path.endswith(".json"):
    text, n = re.subn(r'("version"\s*:\s*")' + re.escape(old) + '"', r"\g<1>" + new + '"', text, count=1)
  else:
    text, n = re.subn(
      r'(\[package\][^\[]*?\nversion\s*=\s*")' + re.escape(old) + '"', r"\g<1>" + new + '"', text, count=1
    )
  if n != 1:
    helpers.print_error(f"Cannot write the version into {path}.")
    sys.exit(1)
  with open(path, "w") as f:
    f.write(text)
  files = [path]
  if path.endswith("Cargo.toml"):
    with open(path, "rb") as f:
      name = tomllib.load(f).get("package", {}).get("name", "")
    for lock in (os.path.join(os.path.dirname(path), "Cargo.lock"), "Cargo.lock"):
      if name and os.path.isfile(lock):
        with open(lock) as f:
          text = f.read()
        text, n = re.subn(
          r'(\[\[package\]\]\nname = "' + re.escape(name) + r'"\nversion = ")' + re.escape(old) + '"',
          r"\g<1>" + new + '"',
          text,
          count=1,
        )
        if n == 1:
          with open(lock, "w") as f:
            f.write(text)
          files.append(lock)
        break
  return files


def run_tasks(tasks):
  """Run each task of a preflight list with mise run."""
  for task in tasks:
    if not helpers.has_own_task(task):
      helpers.print_error(f"The preflight task {task} does not exist.")
      sys.exit(2)
  for task in tasks:
    must("mise", "run", task)


def tag(name, push):
  """Call git:tag on HEAD."""
  must("mise", "run", "git:tag", name, *(["--push"] if push else []))


def tag_at(commit, name, push):
  """Tag <commit>: git:tag tags HEAD, so a commit that is not HEAD is checked
  out alone for the tag, and the branch comes back after it."""
  if git("rev-parse", "HEAD")[1] == git("rev-parse", commit)[1]:
    tag(name, push)
    return
  branch = git("rev-parse", "--abbrev-ref", "HEAD")[1]
  must("git", "switch", "--quiet", "--detach", commit)
  try:
    tag(name, push)
  finally:
    must("git", "switch", "--quiet", branch)


def watch(workflow, name):
  """Watch the run of <workflow> that the push of the tag <name> started."""
  if not helpers.has_tool("gh"):
    helpers.print_warn(f"No gh: follow the run of {workflow} on the forge.")
    return
  helpers.print_subheader(f"Watching {workflow} for {name} ...")
  for _ in range(20):
    out = helpers.tool(
      "gh",
      "run",
      "list",
      "--workflow",
      workflow,
      "--limit",
      "20",
      "--json",
      "databaseId,headBranch",
      stdout=subprocess.PIPE,
      text=True,
    ).stdout
    for run in json.loads(out or "[]"):
      if run.get("headBranch") == name:
        rc = helpers.tool("gh", "run", "watch", str(run["databaseId"]), "--exit-status").returncode
        if rc != 0:
          sys.exit(rc)
        return
    time.sleep(3)
  helpers.print_warn(f"No run of {workflow} for {name} yet: gh run list --workflow={workflow}")


def finish(name, push, workflow):
  if push:
    if workflow:
      watch(workflow, name)
    helpers.print_success(f"Released {name}")
  else:
    helpers.print_success(f"Tagged {name}")
    helpers.print_warn(f"Push the tag to publish: git push origin {name}")


def pending_release(branch, regex):
  """The newest release commit of <regex> on <branch> whose tag is missing, as
  (commit, tag), or None."""
  code, out = git("log", branch, "--format=%H %s", "--grep=^ops: release ")
  if code != 0:
    return None
  for line in out.splitlines():
    commit, _, subject = line.partition(" ")
    name = subject.removeprefix("ops: release ")
    if regex.match(name):
      return None if tag_exists(name) else (commit, name)
  return None


def landed_commit(branch, commit):
  """The first commit of the first-parent line of <branch> that has <commit>."""
  line = git("rev-list", "--first-parent", branch)[1].splitlines()
  if commit in line:
    return commit
  after = git("rev-list", "--first-parent", "--ancestry-path", "--reverse", f"{commit}..{branch}")[1].splitlines()
  return after[0] if after else None


def release_task(sec, dry_run):
  """Run the preflight tasks, then mise run <task> <args...>. --dry-run
  prints the command and runs nothing; the task never gets --dry-run."""
  task = sec["task"]
  args = sec.get("args") or []
  preflight = sec.get("preflight") or []
  command = shlex.join(["mise", "run", task, *args])
  if dry_run:
    for name in preflight:
      helpers.print_info(f"Would run: mise run {name}")
    helpers.print_info(f"Would run: {command}")
    return 0
  run_tasks(preflight)
  if not helpers.has_own_task(task):
    helpers.print_error(f"The task {task} does not exist.")
    return 2
  must("mise", "run", task, *args)
  helpers.print_success(f"Ran {command}")
  return 0


def release_tag(project, kind, sec, folder, push, dry_run):
  template = sec["tag"]
  branch = sec.get("branch") or "main"
  workflow = sec.get("workflow") or ""
  regex = tag_regex(template)

  current = git("rev-parse", "--abbrev-ref", "HEAD")[1]
  if current != branch:
    helpers.print_error(f"On '{current}', not '{branch}'. Switch to {branch} first: git switch {branch}")
    return 1
  if git("status", "--porcelain")[1]:
    helpers.print_error("The tree has uncommitted or untracked files. Commit or remove them first.")
    return 1

  pending = pending_release(branch, regex)
  if pending:
    commit, name = pending
    target = landed_commit(branch, commit)
    if not target:
      helpers.print_error(f"The release commit of {name} is not on {branch}.")
      return 1
    helpers.print_subheader(f"Tagging {name}, which a run before did not tag ...")
    if dry_run:
      helpers.print_info(f"Would tag {target[:12]} as {name}")
      return 0
    tag_at(target, name, push)
    finish(name, push, workflow)
    return 0

  source = sec.get("from")
  if source:
    other = value(f'repo.release.{project}."{source}".tag')
    v = last_version(other)
    if v is None:
      helpers.print_error(f"No tag of release:{project}:{source} yet. Release it first.")
      return 1
    from_tag = other.replace("{version}", show(v))
    name = template.replace("{version}", show(v))
    if tag_exists(name):
      helpers.print_info(f"{name} already exists: nothing to promote")
      return 0
    if git("merge-base", "--is-ancestor", from_tag, "HEAD")[0] != 0:
      helpers.print_error(f"{branch} does not contain {from_tag}. Land that release on {branch} first.")
      return 1
    helpers.print_subheader(f"Promoting {from_tag} to {name} ...")
    if dry_run:
      helpers.print_info(f"Would tag HEAD of {branch} as {name}")
      return 0
    tag(name, push)
    finish(name, push, workflow)
    return 0

  level = value(f'releases."{project}"') or "NONE"
  if level not in LEVELS or level == "NONE":
    helpers.print_info(f"Nothing to release: the level of {project} is NONE")
    return 0
  version = sec.get("version") or "tag"
  if version == "tag":
    old = last_version(template) or (0, 0, 0)
    file = None
  else:
    file = os.path.normpath(os.path.join(folder, version))
    old = read_version(file)
  new = bump(old, level)
  name = template.replace("{version}", show(new))
  if tag_exists(name):
    helpers.print_error(f"The tag {name} already exists.")
    return 1
  helpers.print_info(f"{project}: {show(old)} -> {show(new)} ({level}), tag {name}")
  if dry_run:
    return 0

  helpers.print_subheader("Running the preflight tasks ...")
  run_tasks(sec.get("preflight") or [])

  landing = value(f'repo.branches."{branch}".landing') or "direct-merge"
  work = branch if landing == "direct-commit" else f"release/{name}"
  helpers.print_subheader(f"Committing the release {name} on {work} ...")
  if work != branch:
    must("git", "switch", "--quiet", "-c", work)
  files = write_version(file, show(old), show(new)) if file else []
  bootstrap("config", "unset", f'releases."{project}"')
  must("git", "add", "--", *files, ".config/bootstrap")
  must("git", "commit", "--quiet", "-m", f"ops: release {name}")
  if work == branch and push:
    # A direct commit is on no branch of origin yet, and git:tag --push needs
    # origin to have HEAD.
    must("git", "push", "--quiet", "origin", branch)

  if work != branch:
    must("mise", "run", f"git:merge:{branch}", work)
    if landing == "pr":
      must("git", "switch", "--quiet", branch)
      helpers.print_success(f"Opened the request for {name}")
      helpers.print_warn(f"After the merge, run this task again on {branch}: it makes the tag")
      return 0
    must("git", "switch", "--quiet", branch)
    must("git", "branch", "--quiet", "-d", work)

  helpers.print_subheader(f"Tagging {name} ...")
  tag(name, push)
  if work == branch and not push:
    helpers.print_warn(f"Push the release commit first: git push origin {branch}")
  finish(name, push, workflow)
  return 0


def main(project, kind):
  os.chdir(os.environ["MISE_PROJECT_ROOT"])
  push = os.environ.get("usage_push") == "true"
  dry_run = os.environ.get("usage_dry_run") == "true"
  sec = value(f'repo.release."{project}"."{kind}"')
  folder = value(f'repo.projects."{project}".folder') or "."
  helpers.print_header(f"Releasing {project} ({kind}) ...")
  if sec.get("type") == "task":
    return release_task(sec, dry_run)
  return release_tag(project, kind, sec, folder, push, dry_run)
